-- Directus metadata for inline parameter fields.
-- Generated once by scripts/flatten_param_fields.py (from the param tables, now dropped); since then this file
-- is maintained by hand. machining_operation_subtype keeps the stored MT-/MM- codes (migration 173). Run AFTER the schema
-- migration 20260623000032 and AFTER configure_directus.sql.

BEGIN;

-- Remove O2M parameter panels from parent forms
DELETE FROM directus_fields WHERE field IN ('tensile_test_params','hardness_test_params','charpy_test_params','compression_test_params','sem_params','xrd_params','machining_params','sintering_params','heat_treatment_params','deformation_params','am_params') AND collection IN ('manufacturing_operations','test_sessions');
-- Remove the now-obsolete param collections, fields and relations
DELETE FROM directus_relations WHERE many_collection IN ('tensile_test_params','hardness_test_params','charpy_test_params','compression_test_params','sem_params','xrd_params','machining_params','sintering_params','heat_treatment_params','deformation_params','am_params') OR one_collection IN ('tensile_test_params','hardness_test_params','charpy_test_params','compression_test_params','sem_params','xrd_params','machining_params','sintering_params','heat_treatment_params','deformation_params','am_params');
DELETE FROM directus_fields    WHERE collection IN ('tensile_test_params','hardness_test_params','charpy_test_params','compression_test_params','sem_params','xrd_params','machining_params','sintering_params','heat_treatment_params','deformation_params','am_params');
DELETE FROM directus_collections WHERE collection IN ('tensile_test_params','hardness_test_params','charpy_test_params','compression_test_params','sem_params','xrd_params','machining_params','sintering_params','heat_treatment_params','deformation_params','am_params');

-- Idempotent: clear any previously-inserted inline param fields before re-inserting
-- (no base columns on these tables use these prefixes).
DELETE FROM directus_fields WHERE collection='manufacturing_operations'
    AND (field LIKE 'machining\_%' OR field LIKE 'sintering\_%' OR field LIKE 'ht\_%'
         OR field LIKE 'deform\_%' OR field LIKE 'am\_%');
DELETE FROM directus_fields WHERE collection='test_sessions'
    AND (field LIKE 'tensile\_%' OR field LIKE 'hardness\_%' OR field LIKE 'charpy\_%'
         OR field LIKE 'compression\_%' OR field LIKE 'sem\_%' OR field LIKE 'xrd\_%');

-- ── tensile_test_params → test_sessions (inline, shows when test_type=tensile) ──

-- ── hardness_test_params → test_sessions (inline, shows when test_type=hardness) ──

-- ── charpy_test_params → test_sessions (inline, shows when test_type=charpy) ──

-- ── compression_test_params → test_sessions (inline, shows when test_type=compression) ──

-- ── sem_params → test_sessions (inline, shows when test_type=sem) ──

-- ── xrd_params → test_sessions (inline, shows when test_type=xrd) ──

-- ── machining_params → manufacturing_operations (inline, shows when process_category=machining) ──

-- ── sintering_params → manufacturing_operations (inline, shows when process_category=sintering) ──

-- ── heat_treatment_params → manufacturing_operations (inline, shows when process_category=heat_treatment) ──

-- ── deformation_params → manufacturing_operations (inline, shows when process_category=deformation) ──

-- ── am_params → manufacturing_operations (inline, shows when process_category=additive) ──

COMMIT;
